templates.template:
.xfdevs__hero__container {
    position: relative;
    isolation: isolate;
	display: flex;
	flex-direction: column;
	justify-content: center;
	align-items: center;
	overflow: hidden;
	margin-bottom: 30px;
}

.xfdevs__hero__wrapper {
	display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    text-align: center;
	gap: 1rem;
	    background: radial-gradient(circle at center, rgba(255, 255, 255, 1) 0%, rgba(255, 255, 255, 1) 20%, rgba(255, 255, 255, 0.98) 35%, rgba(255, 255, 255, 0.9) 45%, rgba(255, 255, 255, 0.6) 55%, rgba(255, 255, 255, 0.2) 65%, rgba(255, 255, 255, 0) 75%);
}

.xfdevs__hero__announcement__badge {
	display: flex;
	border-radius: 9999px;
	padding: 7px 7px;
	box-shadow: 0px 0px 80px 0px rgba(0, 0, 0, 0.1), 0px 4px 4px 0px rgba(0, 0, 0, 0.02), 0px 0px 4px 0px rgba(15, 73, 106, 0.05) 
}

.xfdevs__hero__announcement__tag {
	font-weight: bold;
	color: #367ef4;
	margin-right: .275rem;
}

.xfdevs__hero__heading__container {
	max-width: 720px;
}

.xfdevs__hero__heading__container h1, p {
	padding: 0;
	margin: 0;
}

.xfdevs__hero__heading__container h1, p {
	margin-bottom: 1.25rem;
}

.xfdevs__hero__heading__container h1.xfdevs__hero__heading {
	letter-spacing: 0;
	line-height: 120%;
	font-size: 4rem;
	font-weight: 700;
}

.xfdevs__hero__heading__container h1.xfdevs__hero__heading span {
	color: transparent;
	background: linear-gradient(to right, #3380F5, #B0CEFB); /* Your gradient */
	-webkit-background-clip: text;
  	-webkit-text-fill-color: transparent;
}

.xfdevs__hero__heading__container p {
	max-width: 500px;
	color: #595959;
	font-size: 16px
}

.xfdevs__hero__heading__container {
	display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
}

/*-------------------------------------------------------------------------*/
/* XFDEVS - HERO CAROUSEL
/*-------------------------------------------------------------------------*/

.xfdevs__hero__carousel {
  position: fixed;
  width: 100vw;
  overflow: hidden;
  white-space: nowrap;
  padding: 10px 0;
  z-index: -1;
}

.xfdevs__hero__carousel__content {
    display: inline-block;
    padding-left: 100%; /* Start off-screen on right */
    animation: hero-carousel 45s linear infinite;
}

.xfdevs__hero__carousel__content {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: 1rem;
}


@keyframes hero-carousel {
    0% {
      transform: translateX(0%);
    }
    100% {
      transform: translateX(-100%);
    }
  }

.xfdevs__hero__carousel::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 80px;  /* width of fade */
  height: 100%;
  pointer-events: none;  /* so it doesn’t block clicks */
  background: linear-gradient(
    to right,
    rgba(255, 255, 255, 1) 0%,
    rgba(255, 255, 255, 0.8) 50%,
    rgba(255, 255, 255, 0) 100%
  );
  z-index: 10;
}


.xfdevs__hero__carousel::after {
  content: "";
  position: absolute;
  right: 0;
  top: 0;
  width: 80px;
  height: 100%;
  pointer-events: none;
  background: linear-gradient(
    to left,
    rgba(255, 255, 255, 1) 0%,
    rgba(255, 255, 255, 0.8) 50%,
    rgba(255, 255, 255, 0) 100%
  );
  z-index: 10;
}

.xfdevs__hero__carousel:hover .xfdevs__hero__carousel__content {
  animation-play-state: paused;
}

.xfdevs__hero__button__container {
	margin-bottom: 30px;
}

.xfdevs__hero__partners {
	position: relative;
	display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
	z-index: 30;
	margin-bottom: 30px;
}

.xfdex__hero__partners__heading {
	text-transform: uppercase;
	font-weight: 500;
	letter-spacing: .05em;
	font-size: .75rem;
	margin-bottom: 1rem;
	color: #595959;
}

.xfdevs__hero__partners__list {
	display: flex;
	gap: .8rem;
}

.xfdevs__hero__partner span {
	font-size: .875rem;
	color: #595959;
	font-weight: 600;
}

.xfdevs__hero__partner {
	display: flex;
	align-items: center;
	gap: .375rem;
	list-style: none;
	filter: grayscale(100%);
		    transform: scale(1);
    transition: all .3s ease;
}

.xfdevs__hero__partner:hover {
	filter: grayscale(0%);
    transform: scale(1.05);
}

.xfdevs__hero__partner a {
	display: flex;
    align-items: center;
}

.xfdevs__hero__stat__items {
	position: relative;
	z-index: 30;
	max-width: 800px;
	margin: 0 auto;
	width: 100dvh;
	box-shadow: 0px 10px 40px 0px rgba(17, 20, 48, 0.05);
	background: #FFF;
    backdrop-filter: blur(20px);
	padding: .75rem 1.25rem;
	border-radius: 9999px;
	display: flex;
	flex-wrap: wrap;
	justify-content: center;
	align-items: center;
	gap: 1.25rem;
	margin-bottom: 5rem;
}

.xfdevs__hero__stats__item {
	display: flex;
	align-items: center;
	gap: .5rem;
}

.xfdevs__hero__stats__item span {
	font-size: .875rem;
	color: #595959;
}

.xfdevs__hero__stats__glow {
	--blur-value: 150px;
	height: 250px;
	width: 250px;
	border-radius: 9999px;
	opacity: .4;
	filter: blur(var(--blur-value));
}

.xfdevs__hero__stats__glow.puple {
	background-color: #7315d1;	
}

.xfdevs__hero__stats__glow.blue {
	background-color: #0967f4;
}

.xfdevs__hero__stats__glow__container {
	position: absolute;
    display: flex;
    z-index: 20;
    height: 300px;
	bottom: -10rem;
    width: 100%;
    max-width: 800px;
    justify-content: space-between;
}


/*-------------------------------------------------------------------------*/
/* XFDEVS - HERO RESOURCE CARD
/*-------------------------------------------------------------------------*/

.xfdevs__hero__resource__card {
  position: relative;
  overflow: hidden;
  border: 1px solid #b9b9b955;
  padding: .5rem;
  border-radius: 2rem;
  height: 450px;

  display: flex;
  flex-direction: column; /* stack children vertically */
}

.xfdevs__hero__resource__image__container {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;      
  border-radius: 1.5rem;
padding: .5rem;
}

.xfdevs__hero__resource__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 2rem;
  display: block;
}

.xfdevs__hero__resource__content {
 position: relative;
  z-index: 1;
  padding: .8rem;
  margin-top: auto;
}

.xfdevs__hero__resource__info {
	display: flex;
	flex-direction: column;
	gap: .125rem;
	margin-bottom: 15px;
	color: #FFF;
}

.xfdevs__hero__resource__info span {
	color: #cfcfcf;
}

.xfdevs__hero__author {
	background-color: #676767;
	border-radius: 9999px;
	display: inline-flex;
	gap: .5rem;
	padding: .2rem .3rem;
}

.xfdevs__hero__resource__stats {
	display: flex;
	justify-content: center;
	gap: 1rem;
}

.xfdevs__hero__resource__stat_item {
	display: flex;
	flex-direction: column;
	justify-content: center;
	align-items: center;
	gap: .3rem;
	padding: 1rem;
	color: #FFF;
}

.xfdevs__hero__resource__button__wrapper {
	display: flex;
	justify-content: center;
}

.xfdevs__hero__resource__username {
	margin-right: .3rem;
}

.xfdevs__hero__resource__image__blur {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 50%;

  backdrop-filter: blur(15px);
  -webkit-backdrop-filter: blur(15px);


  -webkit-mask-image: linear-gradient(to top, black 70%, transparent 100%);
  mask-image: linear-gradient(to top, black 70%, transparent 100%);

  pointer-events: none;
  z-index: 0.5;
  border-radius: 0 0 2rem 2rem;
}
